	export default {
    layout: 'home',
    async asyncData({ $content, params }) {
			const details = await $content(`going-to-college/${params.slug}`).fetch();
      const lang = params.slug;
			return {
				details,
        lang,
			}
		},
		head() {
			if(this.details) {
				return {
					title: this.details.pageTitle,
					meta: [
						{
						hid: 'description',
						name: 'description',
						content: this.details.pageDescription
						}
					],
				}
			}
		}
	}
